const stores=[{id:'all',name:'全部门店',sales:186420,target:210000,cost:.348,labor:.228,profit:.123,orders:3540},{id:'s1',name:'中心广场店',sales:42680,target:45000,cost:.326,labor:.21,profit:.17,orders:820},{id:'s2',name:'万象城店',sales:38450,target:42000,cost:.332,labor:.219,profit:.149,orders:702},{id:'s3',name:'滨江店',sales:28960,target:38000,cost:.392,labor:.268,profit:-.023,orders:594},{id:'s4',name:'大学城店',sales:35120,target:39000,cost:.341,labor:.218,profit:.131,orders:756},{id:'s5',name:'高新园店',sales:41210,target:46000,cost:.358,labor:.236,profit:.103,orders:668}];
const previous=[{sales:43920,orders:842,profit:.178},{sales:39260,orders:726,profit:.159},{sales:33580,orders:655,profit:.045},{sales:34280,orders:728,profit:.126},{sales:43360,orders:715,profit:.131}];
stores.slice(1).forEach((s,i)=>{s.previousSales=previous[i].sales;s.previousOrders=previous[i].orders;s.previousProfit=previous[i].sales*previous[i].profit});
stores[0].previousSales=stores.slice(1).reduce((n,s)=>n+s.previousSales,0);stores[0].previousOrders=stores.slice(1).reduce((n,s)=>n+s.previousOrders,0);stores[0].previousProfit=stores.slice(1).reduce((n,s)=>n+s.previousProfit,0);
for(const key of ['cost','labor','profit']) stores[0][key]=stores.slice(1).reduce((n,s)=>n+s.sales*s[key],0)/stores[0].sales;
const state={store:'all',day:'day',date:'2026-09-18',period:'7',rank:'risk'};const titles={home:'老板经营看板',revenue:'营业收入分析',profit:'经营利润',cost:'食材成本率',labor:'人工成本率',cash:'资金概览',stores:'门店经营对比',alerts:'待关注事项',quality:'顾客与服务',store:'门店经营详情',orders:'订单与客单价'};let savedScroll={};
const iso=d=>d.toISOString().slice(0,10);
const parseDate=v=>new Date(v+'T00:00:00Z');
const shiftDate=(v,n)=>{const d=parseDate(v);d.setUTCDate(d.getUTCDate()+n);return iso(d)};
function validDate(v){return /^\d{4}-\d{2}-\d{2}$/.test(v)&&!Number.isNaN(parseDate(v).getTime())&&iso(parseDate(v))===v}
function dateRange(){const selected=validDate(state.date)?state.date:'2026-09-18',d=parseDate(selected);if(state.day==='week'){const start=shiftDate(selected,-((d.getUTCDay()+6)%7));return {start,end:shiftDate(start,6)}}if(state.day==='month')return {start:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),1))),end:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()+1,0)))};return {start:selected,end:selected}}
function comparisonRange(){const r=dateRange();if(state.day==='month'){const d=parseDate(r.start);return {start:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth()-1,1))),end:iso(new Date(Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),0)))}}return {start:shiftDate(r.start,-7),end:shiftDate(r.end,-7)}}
const rangeText=(r=dateRange())=>r.start+' ～ '+r.end;
function rangeFactor(r){let n=0;for(let d=r.start;d<=r.end;d=shiftDate(d,1)){const k=Math.round((parseDate(d)-parseDate('2026-09-18'))/86400000);n+=1+((k%7+7)%7)*.012}return n}
function normalizeFilters(){if(!['day','week','month'].includes(state.day))state.day='day';if(!validDate(state.date))state.date='2026-09-18'}
const money=n=>Math.round(n).toLocaleString('zh-CN');const pct=n=>(n*100).toFixed(1)+'%';const value=n=>Math.abs(n)>=10000?(n/10000).toFixed(2):money(n);const unit=n=>Math.abs(n)>=10000?'万':'元';const factor=()=>rangeFactor(dateRange());const current=()=>{const s=stores.find(s=>s.id===state.store)||stores[0],f=factor();return {...s,sales:Math.round(s.sales*f),target:Math.round(s.target*f),orders:Math.round(s.orders*f),previousSales:Math.round(s.previousSales*rangeFactor(comparisonRange())),previousOrders:Math.round(s.previousOrders*rangeFactor(comparisonRange())),previousProfit:s.previousProfit*rangeFactor(comparisonRange())}};
const currentRoute=()=>location.hash.slice(1)||'home';function persist(){history.replaceState({demo:true,filters:{...state},scroll:window.scrollY,depth:history.state?.depth||0},'')}function go(route,store){persist();if(store)state.store=store;history.pushState({demo:true,filters:{...state},scroll:0,depth:(history.state?.depth||0)+1},'', '#'+route);render();window.scrollTo(0,0)}function section(t,sub=''){return `<div class="section-title"><span>${t}</span><small>${sub}</small></div>`}function foot(){return '<div class="footer">演示数据 · 非真实经营数据<br>移动端交互原型</div>'}function filter(){return `<div class="filters"><select aria-label="门店范围" id="store-filter">${stores.map(s=>`<option value="${s.id}" ${state.store===s.id?'selected':''}>${s.name}</option>`).join('')}</select></div><div class="date-filter"><div class="date-type"><span>日期类型：</span><div class="date-tabs" role="group" aria-label="日期类型">${[['day','日'],['week','周'],['month','月']].map(([id,n])=>`<button data-date-type="${id}" aria-pressed="${state.day===id}" class="${state.day===id?'selected':''}">${n}</button>`).join('')}</div></div><div class="date-range-row"><span>日期：</span><button id="date-open" aria-label="选择统计日期：${rangeText()}"><span>${dateRange().start}</span><span class="date-separator">～</span><span>${dateRange().end}</span><span aria-hidden="true">▾</span></button></div></div>`}
function hero(detail){const d=current(),growth=d.sales/d.previousSales-1;return `<div class="hero ${detail?'detail-hero':''}"><div class="brand">${detail?titles[detail]:'示范餐饮 · 老板看板'}</div><div class="hero-sub">${detail?d.name:'直营 '+(state.store==='all'?'5 家门店':d.name)+' · '+(state.day==='day'?dateRange().start:dateRange().start+'—'+dateRange().end)+'经营数据'}</div>${detail?'':`<button class="hero-primary" data-go="revenue"><label>${periodName()}净营业额 <span>查看分析 ›</span></label><div class="hero-score">${value(d.sales)}<small>${unit(d.sales)}</small></div><div class="hero-comparison"><span>较${compareName()} ${growth>=0?'+':''}${pct(growth)}</span><span>目标达成 ${pct(d.sales/d.target)}</span></div></button>`}${filter()}</div>`}
function metric(label,note,v,route,bad=true){return `<button class="metric-row" data-go="${route}"><div class="row"><strong>${label} ▸</strong><b>${v}<i class="dot ${bad?'red':'green'}"></i></b></div><div class="minor ${bad?'red':'green'}">${note}</div></button>`}
function kpi(label,v,u,note,route,bad=false){return `<button class="kpi" data-go="${route}"><div class="kpi-label">${label} ▸</div><div class="kpi-value">${v}<small>${u}</small></div><div class="kpi-note ${bad?'red':'green'}">${note}</div></button>`}
function chart(kind='sales'){const s=current();const arr=state.period==='30'?[72,95,98,108,127,104,99,113,96,88,91,96,106,103,79,92,80,106,99,125,106,79,98,106,108,114,112,96,104,89]:[91,99,103,94,107,96,89];const ending=kind==='cost'?s.cost*100:kind==='profit'?s.profit*100:s.sales/s.target*100;const vals=arr.map(v=>ending+(v-arr[arr.length-1])*(kind==='cost'?.09:kind==='profit'?.06:1));const ref=kind==='cost'?35:kind==='profit'?15:100;const max=Math.ceil((Math.max(...vals,ref)+2)/5)*5,min=Math.floor((Math.min(...vals,ref)-2)/5)*5;const refY=145-(ref-min)/(max-min)*113;const pts=vals.map((v,i)=>[32+i*300/(vals.length-1),145-(v-min)/(max-min)*113]);return `<svg class="chart" viewBox="0 0 350 179" role="img" aria-label="${state.period}天${kind==='cost'?'食材成本率':kind==='profit'?'利润率':'营收达成率'}趋势"><g>${[0,1,2,3,4].map(i=>`<line x1="32" x2="334" y1="${32+i*28}" y2="${32+i*28}" stroke="#e9edf4" stroke-dasharray="3 3"/><text x="25" y="${36+i*28}" text-anchor="end" class="chart-label">${Math.round(max-i*(max-min)/4)}%</text>`).join('')}</g><polyline points="32,${refY} 334,${refY}" fill="none" stroke="#b8c3d4" stroke-dasharray="4 4"/><polyline points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#518df5" stroke-width="2" stroke-linejoin="round"/>${pts.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="2.7" fill="#518df5" stroke="white"><title>${i+1}日：${vals[i].toFixed(1)}%</title></circle>`).join('')}${[0,1,2,3].map((v,i)=>`<text x="${32+i*100}" y="169" text-anchor="middle" class="chart-label">${shiftDate(dateRange().end,-(Number(state.period)-1)+Math.round(i*(Number(state.period)-1)/3)).slice(5).replace('-','/')}</text>`).join('')}</svg><div class="explain">每日趋势 · 截至 ${dateRange().end}</div><div class="legend"><span><i></i>${kind==='cost'?'食材成本率':kind==='profit'?'利润率':'营收达成率'}</span><span><i class="grey"></i>${kind==='cost'?'目标 35%':kind==='profit'?'参考 15%':'目标 100%'}</span></div>`}
function trends(kind='sales'){return `<div class="card card-pad"><div class="row"><div class="chart-title">${kind==='cost'?'成本率':kind==='profit'?'利润率':'营收达成率'}趋势</div><div><button class="link-btn" data-period="7" ${state.period==='7'?'style="font-weight:700"':''}>7天</button><button class="link-btn" data-period="30" ${state.period==='30'?'style="font-weight:700"':''}>30天</button></div></div>${chart(kind)}</div>`}
function ranks(mode='sales',limit=5){return scopeStores().sort((a,b)=>mode==='cost'?b.cost-a.cost:mode==='profit'?b.sales*b.profit-a.sales*a.profit:b.sales-a.sales).slice(0,limit).map((s,i)=>`<button class="rank" data-store="${s.id}"><div class="row"><span class="name"><span class="num">${i+1}</span>${s.name} ▸</span><span class="amount ${mode==='cost'&&s.cost>.35?'red':''}">${mode==='cost'?pct(s.cost):'¥ '+money(s.sales*factor()*(mode==='profit'?s.profit:1))}</span></div><div class="track"><div style="width:${mode==='cost'?s.cost*200:s.sales/46000*100}%;${mode==='cost'&&s.cost>.35?'background:var(--red)':''}"></div></div><div class="rank-footer"><span>${mode==='profit'?'利润率 '+pct(s.profit):'营业目标 ¥ '+money(s.target*factor())}</span><span class="${s.sales/s.target<.9?'red':''}">达成 ${pct(s.sales/s.target)}</span></div></button>`).join('')}
const periodName=()=>state.day==='day'?'所选日':state.day==='week'?'所选周':'所选月';
const compareName=()=>state.day==='day'?'上周同日':state.day==='week'?'上周':'上月';
const scopeStores=()=>state.store==='all'?stores.slice(1):stores.filter(s=>s.id===state.store);
const signedPct=n=>(n>=0?'+':'')+pct(n);
function issues(){return scopeStores().flatMap(s=>{let a=[];if(s.profit<0)a.push({store:s.id,title:s.name+'出现亏损',value:'−¥ '+money(Math.abs(s.sales*s.profit)*factor()),text:'营收达成 '+pct(s.sales/s.target)+'，食材成本率 '+pct(s.cost),route:'profit',owner:'区域负责人',action:'核对成本与费用，复核低峰时段排班。',priority:1});if(s.cost>.35)a.push({store:s.id,title:s.name+'食材成本超标',value:'+'+(s.cost*100-35).toFixed(1)+'个百分点',text:'较35%目标多支出约 ¥ '+money(s.sales*(s.cost-.35)*factor()),route:'cost',owner:'门店店长 / 采购',action:'检查采购单价、报损和标准用量差异。',priority:2});return a}).sort((a,b)=>a.priority-b.priority)}
function summary(){const d=current(),list=issues(),loss=scopeStores().filter(s=>s.profit<0).length;return `<div class="card card-pad briefing"><div class="brief-title">经营摘要 <span>模拟数据</span></div><p>${periodName()}净营业额较${compareName()}<b class="${d.sales<d.previousSales?'red':'green'}">${d.sales<d.previousSales?'下降':'增长'} ${pct(Math.abs(d.sales/d.previousSales-1))}</b>，距营业目标差 <b>${money(Math.max(0,d.target-d.sales))} 元</b>。${loss?'有 <b class="red">'+loss+' 家门店亏损</b>，优先核查亏损与成本超标。':list.length?'当前无亏损门店，仍需关注成本超标。':'当前范围无亏损及食材成本超标门店。'}</p></div>`}
function issueCard(item){return `<button class="issue-row" data-go="${item.route}" data-scope="${item.store}"><div class="row"><strong>${item.title}</strong><span class="red">${item.value} ›</span></div><div class="minor muted">${item.text}</div><div class="issue-owner">${item.owner} · ${item.priority===1?'优先核查':'关注成本'}</div></button>`}
function businessStats(){const d=current(),p=d.sales*d.profit;return `<div class="card grid">${kpi('预估经营利润',value(p),unit(p),'较'+compareName()+' '+(p>=d.previousProfit?'+':'−')+money(Math.abs(p-d.previousProfit))+'元','profit',p<d.previousProfit)}${kpi('经营利润率',(d.profit*100).toFixed(1),'%','较对比期 '+((d.profit-d.previousProfit/d.previousSales)*100).toFixed(1)+' 个百分点','profit',d.profit<d.previousProfit/d.previousSales)}${kpi('可用资金 · 品牌','86.52','万','当前余额，不随经营范围变化','cash')}${kpi('近7天应付 · 品牌','32.80','万','付款后余额 53.72 万','cash')}</div>`}
function home(){const d=current(),list=issues(),badStores=new Set(list.map(x=>x.store)).size;return hero()+`<div class="stamp"><span>演示数据 · 随所选日期汇总</span><button class="link-btn" data-info="opportunity">指标口径 ⓘ</button></div>${businessStats()}${summary()}${section('经营关注事项',badStores+' 家门店 · '+list.length+' 项')}<div class="card">${list.length?list.slice(0,3).map(issueCard).join(''):'<div class="card-pad minor green">当前范围暂无亏损或成本超标事项。</div>'}${list.length?'<button class="wide-link" data-go="alerts">查看全部事项与排查建议 ›</button>':''}</div>${section('生意为什么变了','较'+compareName())}<div class="card grid">${kpi('有效订单',money(d.orders),'单',signedPct(d.orders/d.previousOrders-1),'orders',d.orders<d.previousOrders)}${kpi('单均消费',(d.sales/d.orders).toFixed(2),'元',signedPct((d.sales/d.orders)/(d.previousSales/d.previousOrders)-1),'orders',(d.sales/d.orders)<(d.previousSales/d.previousOrders))}</div><div class="card">${metric('营业目标缺口','点击查看渠道表现与门店差额','¥ '+money(Math.max(0,d.target-d.sales)),'revenue')}</div>${section('门店经营对比','先看利润承压的门店')}<div class="card">${storeCompare(3,'risk')}<button class="wide-link" data-go="stores">查看全部门店 ›</button></div>${section('顾客与服务','当前待处理')}<div class="card"><button class="issue-row" data-go="quality"><div class="row"><strong>未处理客诉</strong><span class="red">${complaints().length} 起 ›</span></div><div class="minor muted">${complaints().length?'查看涉及门店、问题与处理进度':'当前范围暂无待处理客诉'}</div></button></div>${foot()}`}
function storeCompare(limit=5,sortMode=state.rank){const list=scopeStores().sort((a,b)=>sortMode==='sales'?b.sales-a.sales:sortMode==='target'?a.sales/a.target-b.sales/b.target:a.profit-b.profit);return list.slice(0,limit).map(st=>`<button class="store-compare" data-store="${st.id}"><div class="row"><strong>${st.name} ›</strong><span class="tag ${st.profit<0?'danger':st.cost>.35?'warning':''}">${st.profit<0?'亏损':st.cost>.35?'成本偏高':'盈利'}</span></div><div class="store-numbers"><div><label>净营业额</label><b>¥ ${money(st.sales*factor())}</b></div><div><label>预估利润</label><b class="${st.profit<0?'red':''}">${st.profit<0?'−':''}¥ ${money(Math.abs(st.sales*st.profit)*factor())}</b></div><div><label>目标达成</label><b class="${st.sales/st.target<.9?'red':''}">${pct(st.sales/st.target)}</b></div></div></button>`).join('')}
function storesPage(){return hero('stores')+`<div class="card"><div class="tabs">${[['risk','利润率从低到高'],['sales','营收从高到低'],['target','达成率从低到高']].map(([id,n])=>`<button class="${state.rank===id?'active':''}" data-rank="${id}">${n}</button>`).join('')}</div>${storeCompare()}</div><div class="notice">不同面积、商圈门店不宜只比营业额；先检查利润率和目标达成，再进入门店定位原因。</div>${foot()}`}
function alerts(){const list=issues();return hero('alerts')+`<div class="notice">以下为演示规则识别出的待核查事项，排查建议不代表已确认原因。阈值仅供原型演示。</div>${list.map(item=>`<div class="card">${issueCard(item)}<div class="action-note"><b>建议排查</b><p>${item.action}</p><span>跟进角色：${item.owner}</span></div></div>`).join('')||'<div class="card card-pad">当前范围暂无待关注事项。</div>'}${foot()}`}
function complaints(){return [{store:'s3',type:'出餐等待过久',time:'09/17 19:42',status:'店长核查中',note:'核查当班出餐记录，并回访顾客。'},{store:'s5',type:'外卖漏装餐品',time:'09/17 20:15',status:'待回访',note:'核对打包记录，确认补偿及回访结果。'},{store:'s3',type:'服务响应不及时',time:'09/17 20:38',status:'待联系顾客',note:'核查现场服务记录，确认顾客诉求。'}].filter(x=>state.store==='all'||x.store===state.store)}
function quality(){return hero('quality')+`<div class="notice">客诉为当前待处理事项，不随经营日期变化；可按门店筛选。全部为模拟案例。</div>${section('待处理客诉',complaints().length+' 起')}${complaints().map(x=>`<div class="card card-pad"><div class="row"><b style="font-size:14px">${x.type}</b><span class="tag warning">${x.status}</span></div><p class="minor muted">${stores.find(s=>s.id===x.store).name} · ${x.time}</p><p class="minor">${x.note}</p><button class="wide-link" data-store="${x.store}">查看门店经营 ›</button></div>`).join('')||'<div class="card card-pad minor green">当前门店暂无待处理客诉。</div>'}${foot()}`}
function revenue(){const s=current();return hero('revenue')+`<div class="card card-pad"><div class="chart-title">营收达成概览</div><div class="row progress-label"><span>营收达成率</span><b class="red">${pct(s.sales/s.target)}</b></div><div class="big-track"><div style="width:${Math.min(100,s.sales/s.target*100)}%"></div></div><div class="explain">实际营收 ${money(s.sales)} 元 ｜ 目标营收 ${money(s.target)} 元</div></div>${trends()}${section('营业渠道构成')}<div class="card">${[['堂食',.58],['美团外卖',.28],['饿了么',.14]].map(([n,p])=>`<div class="rank"><div class="row"><span class="name">${n}</span><span class="amount">¥ ${money(s.sales*p)} · ${pct(p)}</span></div><div class="track"><div style="width:${p*100}%"></div></div></div>`).join('')}</div>${section('总营收差额拆解')}<div class="card card-pad"><div class="row"><span class="progress-label">较目标差额</span><b class="red">−¥ ${money(s.target-s.sales)}</b></div></div>${[['堂食订单量',.45],['堂食单均价',-.1],['外卖订单量',.5],['外卖单均价',.15]].map(([n,p])=>`<div class="card attribution ${p<0?'good':''}"><div class="attribution-top"><b>${n}</b><b>${p<0?'+':'−'}¥ ${money((s.target-s.sales)*Math.abs(p))}</b></div><div class="attribution-bottom"><div class="row explain"><span>差额贡献占比</span><span>${pct(p)}</span></div><div class="track"><div style="width:${Math.abs(p)*100}%"></div></div></div>`).join('')}<div class="explain" style="padding:0 14px">模拟拆解：正贡献表示扩大缺口，负贡献表示抵消缺口。</div>${section('门店营收对比')}<div class="card">${ranks()}</div>${foot()}`}
function profit(){const s=current();const rows=[['净营业额',s.sales],['食材成本',s.sales*s.cost],['人工成本',s.sales*s.labor],['租金及其他费用',s.sales*(1-s.cost-s.labor-s.profit)],['预估经营利润',s.sales*s.profit]];return hero('profit')+`<div class="notice">按食材、人工及费用分摊预估，非财务结账净利润。${s.profit<0?'当前门店出现亏损，建议先核查收入缺口、食材耗用与排班。':'同时关注利润额与利润率，避免只看收入增长。'}</div><div class="card grid">${kpi('预估经营利润',value(s.sales*s.profit),unit(s.sales*s.profit),'当前统计范围','profit',s.profit<0)}${kpi('经营利润率',(s.profit*100).toFixed(1),'%','利润 ÷ 净营业额','profit',s.profit<0)}</div>${section('利润构成')}<div class="card table-wrap"><table><thead><tr><th>项目</th><th>金额 / 元</th><th>占营收比</th></tr></thead><tbody>${rows.map(([n,v])=>`<tr><td>${n}</td><td>${money(v)}</td><td>${pct(v/s.sales)}</td></tr>`).join('')}</tbody></table></div>${trends('profit')}${section('利润承压门店')}<div class="card">${storeCompare(5,'risk')}</div>${foot()}`}
function cost(labor=false){const s=current(),rate=labor?s.labor:s.cost,target=labor?.22:.35,route=labor?'labor':'cost';return hero(route)+`<div class="card card-pad"><div class="row"><span class="chart-title">${labor?'人工':'食材'}成本率</span><b class="${rate>target?'red':'green'}" style="font-size:24px">${pct(rate)}</b></div><div class="big-track"><div style="width:${rate*200}%;background:${rate>target?'var(--red)':'var(--green)'}"></div></div><div class="explain">目标 ≤${pct(target)} ｜ ${rate>target?'超出':'低于'} ${Math.abs(rate-target)*100<.01?'0.0':(Math.abs(rate-target)*100).toFixed(1)} 个百分点</div></div>${section('成本构成')}<div class="card table-wrap"><table><thead><tr><th>项目</th><th>金额 / 元</th><th>占成本比</th></tr></thead><tbody>${(labor?[['固定薪酬',.72],['计时与加班',.18],['社保及福利',.1]]:[['主料耗用',.61],['辅料与调味',.23],['包装耗用',.11],['报损',.05]]).map(([n,p])=>`<tr><td>${n}</td><td>${money(s.sales*rate*p)}</td><td>${pct(p)}</td></tr>`).join('')}</tbody></table></div>${labor?`<div class="card card-pad"><div class="chart-title">用工效率</div><div class="row minor"><span>总工时（模拟）</span><b>${money(s.orders*.12)} 小时</b></div><div class="row minor"><span>每工时营业额</span><b>¥ ${(s.sales/(s.orders*.12)).toFixed(1)}</b></div></div>`:trends('cost')}${section('门店成本对比')}<div class="card">${labor?scopeStores().map(st=>`<button class="rank" data-store="${st.id}"><div class="row"><span class="name">${st.name} ▸</span><b class="${st.labor>.22?'red':'green'}">${pct(st.labor)}</b></div></button>`).join(''):ranks('cost')}</div>${foot()}`}
function cash(){return hero('cash')+`<div class="notice">资金为品牌当前时点余额，不随经营日期和门店筛选变化。</div><div class="card grid">${kpi('可用资金','86.52','万','截至 09/18 08:00','cash')}${kpi('平台待结算','12.64','万','预计未来 3 天到账','cash')}</div>${section('近 7 天付款计划')}<div class="card table-wrap"><table><thead><tr><th>款项</th><th>到期日</th><th>金额 / 元</th></tr></thead><tbody><tr><td>供应商货款</td><td>09/20</td><td>128,000</td></tr><tr><td>员工薪资</td><td>09/22</td><td>146,000</td></tr><tr><td>门店租金</td><td>09/24</td><td>54,000</td></tr><tr><td>合计</td><td>近7天</td><td>328,000</td></tr></tbody></table></div><div class="card card-pad"><div class="row minor"><span>付款后可用资金（不含待结算）</span><b class="green">¥ 537,200</b></div></div>${foot()}`}
function storePage(){const s=current();return hero('store')+`<div class="card grid">${kpi('净营业额',value(s.sales),unit(s.sales),'目标达成 '+pct(s.sales/s.target),'revenue',true)}${kpi('预估经营利润',value(s.sales*s.profit),unit(s.sales*s.profit),'利润率 '+pct(s.profit),'profit')}</div><div class="card opportunity"><h2>门店改善机会</h2>${metric('营收达成率','距目标差额 ¥ '+money(s.target-s.sales),pct(s.sales/s.target),'revenue')}${metric('食材成本率','目标 ≤35%',pct(s.cost),'cost',s.cost>.35)}${metric('人工成本率','目标 ≤22%',pct(s.labor),'labor',s.labor>.22)}</div>${trends()}${foot()}`}
function orders(){const s=current();return hero('orders')+`<div class="card grid">${kpi('有效订单',money(s.orders),'单','已完成且未全额退款','orders')}${kpi('单均消费',(s.sales/s.orders).toFixed(2),'元','以订单为单位，非人均','orders')}</div>${section('渠道订单明细')}<div class="card table-wrap"><table><thead><tr><th>渠道</th><th>订单数</th><th>营业额 / 元</th><th>单均 / 元</th></tr></thead><tbody>${[['堂食',.52,.58],['美团外卖',.32,.28],['饿了么',.16,.14]].map(([n,q,p])=>`<tr><td>${n}</td><td>${money(s.orders*q)}</td><td>${money(s.sales*p)}</td><td>${(s.sales*p/Math.round(s.orders*q)).toFixed(2)}</td></tr>`).join('')}</tbody></table></div>${foot()}`}
function render(restore=false){normalizeFilters();let route=currentRoute();if(!titles[route])route='home';document.title=titles[route]+' · 演示';document.getElementById('app').innerHTML=`<header>${route==='home'?'':`<button id="back" aria-label="返回上一页">‹</button>`}<h1>${titles[route]}</h1><span class="demo">DEMO</span></header>`+({home,revenue,profit,cost:()=>cost(false),labor:()=>cost(true),cash,store:storePage,orders,stores:storesPage,alerts,quality}[route]())+`<dialog id="info"><h3>经营指标口径</h3><p>净营业额：优惠与退款后的营业收入，不等于现金到账。预估经营利润：扣除食材、人工、租金及其他费用，非财务结账净利润。</p><p>日按所选当天、周按周一至周日、月按自然月统计；日对比上周同日，周对比上周，月对比上月；示例门店均为同一组持续经营门店。资金与客诉为当前状态，不随经营日期变化。</p><p>所有数据、目标和排查建议仅用于交互演示。</p><button id="close-info">知道了</button></dialog><dialog id="date-dialog"><form id="date-form"><h3>选择${state.day==='month'?'月份':state.day==='week'?'周内任一天':'日期'}</h3><input id="date-input" aria-label="统计日期" type="${state.day==='month'?'month':'date'}" value="${state.day==='month'?state.date.slice(0,7):state.date}" min="${state.day==='month'?'2020-01':'2020-01-01'}" max="${state.day==='month'?'2035-12':'2035-12-31'}" required><p>${state.day==='week'?'自动选取该日期所在的周一至周日。':state.day==='month'?'自动选取该月第一天至最后一天。':'起止日期均为所选当天。'}演示数据随所选日期生成。</p><div class="date-actions"><button type="button" id="date-cancel">取消</button><button type="submit">确定</button></div></form></dialog>`;
document.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>go(el.dataset.go,el.dataset.scope));document.querySelectorAll('[data-store]').forEach(el=>el.onclick=()=>go('store',el.dataset.store));document.querySelectorAll('[data-rank]').forEach(el=>el.onclick=()=>{state.rank=el.dataset.rank;persist();render()});document.querySelectorAll('[data-period]').forEach(el=>el.onclick=()=>{state.period=el.dataset.period;render()});document.querySelectorAll('[data-info]').forEach(el=>el.onclick=()=>document.getElementById('info').showModal());document.getElementById('close-info').onclick=()=>document.getElementById('info').close();const b=document.getElementById('back');if(b)b.onclick=()=>{if(history.state?.depth>0)history.back();else go('home')};document.getElementById('store-filter').onchange=e=>{state.store=e.target.value;persist();render()};document.querySelectorAll('[data-date-type]').forEach(el=>el.onclick=()=>{state.day=el.dataset.dateType;persist();render()});document.getElementById('date-open').onclick=()=>document.getElementById('date-dialog').showModal();document.getElementById('date-cancel').onclick=()=>document.getElementById('date-dialog').close();document.getElementById('date-form').onsubmit=e=>{e.preventDefault();const v=document.getElementById('date-input').value;const selected=state.day==='month'?v+'-01':v;if(!validDate(selected))return;state.date=selected;persist();render()};if(restore)window.scrollTo(0,savedScroll[route]||0)}
history.scrollRestoration='manual';window.addEventListener('popstate',()=>{if(history.state?.filters)Object.assign(state,history.state.filters);render();window.scrollTo(0,history.state?.scroll||0)});if(history.state?.filters)Object.assign(state,history.state.filters);persist();render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'set_dashboard_filters',description:'设置演示看板门店与日期范围，与页面筛选器同步。',inputSchema:{type:'object',properties:{store:{type:'string',enum:stores.map(s=>s.id)},day:{type:'string',enum:['day','week','month']},date:{type:'string',description:'所选日期，YYYY-MM-DD'}},required:['store','day','date'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!stores.some(s=>s.id===input.store)||!['day','week','month'].includes(input.day)||!validDate(input.date))throw Error('筛选值无效');Object.assign(state,{store:input.store,day:input.day,date:input.date});persist();render();return {store:current().name,day:state.day,date:state.date,range:dateRange(),simulated:true};}})).catch(()=>{});}catch{}}
